pub struct Rng(pub u64);
impl Rng {
    pub fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }
}
pub fn gen_Nat(r: &mut Rng, _m: u64) -> u64 {
    r.next() % 3
}
pub fn gen_Bool(r: &mut Rng, _m: u64) -> bool {
    r.next() % 2 == 0
}
pub fn gen_ListNat(r: &mut Rng, m: u64) -> Rc<List<u64>> {
    let k = r.next() % (m + 1);
    let mut xs = Vec::new();
    for _ in 0..k {
        xs.push(gen_Nat(r, 3));
    }
    let mut l: Rc<List<u64>> = Rc::new(List::Nil);
    for x in xs.into_iter().rev() {
        l = Rc::new(List::Con(x, l));
    }
    l
}
pub fn gen_ListE(r: &mut Rng, m: u64) -> Rc<List<E>> {
    let k = r.next() % (m + 1);
    let mut xs = Vec::new();
    for _ in 0..k {
        xs.push(gen_E(r, 3));
    }
    let mut l: Rc<List<E>> = Rc::new(List::Nil);
    for x in xs.into_iter().rev() {
        l = Rc::new(List::Con(x, l));
    }
    l
}
pub fn gen_ListP(r: &mut Rng, m: u64) -> Rc<List<P>> {
    let k = r.next() % (m + 1);
    let mut xs = Vec::new();
    for _ in 0..k {
        xs.push(gen_P(r, 3));
    }
    let mut l: Rc<List<P>> = Rc::new(List::Nil);
    for x in xs.into_iter().rev() {
        l = Rc::new(List::Con(x, l));
    }
    l
}
pub fn gen_ListOp(r: &mut Rng, m: u64) -> Rc<List<Op>> {
    let k = r.next() % (m + 1);
    let mut xs = Vec::new();
    for _ in 0..k {
        xs.push(gen_Op(r, 3));
    }
    let mut l: Rc<List<Op>> = Rc::new(List::Nil);
    for x in xs.into_iter().rev() {
        l = Rc::new(List::Con(x, l));
    }
    l
}
pub fn gen_E(r: &mut Rng, _m: u64) -> E {
    match r.next() % 1 {
        _ => {
            let f0 = gen_Nat(r, 3);
            let f1 = gen_Nat(r, 3);
            let f2 = gen_Bool(r, 3);
            let f3 = gen_ListNat(r, 3);
            let f4 = gen_Bool(r, 3);
            let f5 = gen_Bool(r, 3);
            let f6 = gen_Bool(r, 3);
            E::E(f0, f1, f2, f3, f4, f5, f6)
        }
    }
}
pub fn gen_St(r: &mut Rng, _m: u64) -> St {
    match r.next() % 1 {
        _ => {
            let f0 = gen_ListE(r, 3);
            let f1 = gen_Nat(r, 3);
            let f2 = gen_Nat(r, 3);
            let f3 = gen_Nat(r, 3);
            let f4 = gen_ListP(r, 3);
            St::St(f0, f1, f2, f3, f4)
        }
    }
}
pub fn gen_P(r: &mut Rng, _m: u64) -> P {
    match r.next() % 1 {
        _ => {
            let f0 = gen_Nat(r, 3);
            let f1 = gen_Bool(r, 3);
            P::P(f0, f1)
        }
    }
}
pub fn gen_Edit(r: &mut Rng, _m: u64) -> Edit {
    match r.next() % 5 {
        0 => {
            let f0 = gen_Nat(r, 3);
            Edit::AddPid(f0)
        }
        1 => {
            let f0 = gen_Nat(r, 3);
            Edit::DropPid(f0)
        }
        2 => Edit::Depart,
        3 => Edit::MarkFenced,
        _ => Edit::UnfenceOne,
    }
}
pub fn gen_Bound(r: &mut Rng, _m: u64) -> Bound {
    match r.next() % 4 {
        0 => Bound::BGranted,
        1 => Bound::BGone,
        2 => Bound::BWaiting,
        _ => Bound::BFenced,
    }
}
pub fn gen_Op(r: &mut Rng, _m: u64) -> Op {
    match r.next() % 10 {
        0 => {
            let f0 = gen_Nat(r, 3);
            let f1 = gen_Bool(r, 3);
            Op::TAsk(f0, f1)
        }
        1 => {
            let f0 = gen_Nat(r, 3);
            let f1 = gen_Nat(r, 3);
            Op::TBind(f0, f1)
        }
        2 => {
            let f0 = gen_Nat(r, 3);
            let f1 = gen_Nat(r, 3);
            Op::TExit(f0, f1)
        }
        3 => {
            let f0 = gen_Nat(r, 3);
            Op::TLeave(f0)
        }
        4 => Op::TFence,
        5 => Op::TUnfence,
        6 => Op::TWait,
        7 => Op::TWaitLeave,
        8 => {
            let f0 = gen_Nat(r, 3);
            Op::TFenced(f0)
        }
        _ => {
            let f0 = gen_Nat(r, 3);
            Op::TResume(f0)
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LawStats {
    pub total: u64,
    pub tested: u64,
    pub vacuous: u64,
    pub failed: u64,
}
impl LawStats {
    pub fn is_vacuous(&self) -> bool {
        self.total > 0 && self.tested == 0
    }
    pub fn passed(&self) -> bool {
        self.failed == 0 && !self.is_vacuous()
    }
}

