/// one_holder_check's seed and draw size: the same stream every target draws.
pub const SEED_ONE_HOLDER_CHECK: u64 = 1000003;
pub const PROPS_ONE_HOLDER_CHECK: u64 = 2000;
pub const PROP_LEN_ONE_HOLDER_CHECK: u64 = 24;
pub fn check_one_holder_check_definedness() -> LawStats {
    let mut s = LawStats {
        total: 0,
        tested: 0,
        vacuous: 0,
        failed: 0,
    };
    for (os_0,) in corpus_one_holder_check() {
        let (ok, v) = law_one_holder_check(os_0);
        s.total += 1;
        if !ok {
            s.failed += 1;
            s.tested += 1;
        } else if v == "vacuous" {
            s.vacuous += 1;
        } else {
            s.tested += 1;
        }
    }
    let mut r = Rng(SEED_ONE_HOLDER_CHECK);
    for _ in 0..PROPS_ONE_HOLDER_CHECK {
        let os_0 = gen_ListOp(&mut r, PROP_LEN_ONE_HOLDER_CHECK);
        let (ok, v) = law_one_holder_check(os_0);
        s.total += 1;
        if !ok {
            s.failed += 1;
            s.tested += 1;
        } else if v == "vacuous" {
            s.vacuous += 1;
        } else {
            s.tested += 1;
        }
    }
    s
}

