/// fifo_check's seed and draw size: the same stream every target draws.
pub const SEED_FIFO_CHECK: u64 = 2000006;
pub const PROPS_FIFO_CHECK: u64 = 2000;
pub const PROP_LEN_FIFO_CHECK: u64 = 24;
pub fn check_fifo_check_definedness() -> LawStats {
    let mut s = LawStats {
        total: 0,
        tested: 0,
        vacuous: 0,
        failed: 0,
    };
    for (os_9,) in corpus_fifo_check() {
        let (ok, v) = law_fifo_check(os_9);
        s.total += 1;
        if !ok {
            s.failed += 1;
            s.tested += 1;
        } else if v == "vacuous" {
            s.vacuous += 1;
        } else {
            s.tested += 1;
        }
    }
    let mut r = Rng(SEED_FIFO_CHECK);
    for _ in 0..PROPS_FIFO_CHECK {
        let os_9 = gen_ListOp(&mut r, PROP_LEN_FIFO_CHECK);
        let (ok, v) = law_fifo_check(os_9);
        s.total += 1;
        if !ok {
            s.failed += 1;
            s.tested += 1;
        } else if v == "vacuous" {
            s.vacuous += 1;
        } else {
            s.tested += 1;
        }
    }
    s
}
